import { mapGetters } from 'vuex'
import Upload from '@/components/safeDanger/Upload/index'
import { orderId, orderAdd, orderUpdate, queryShortNameList, createFlow, backToLastItem, queryNextFlowUsers } from "@/api/safeDanger/report"
import { securitySupervision } from "@/api/safeDanger/networkSecure"
import { getAreaTree, selectShoutUser, machineroomuserId, machineRoomUserAdd, machineRoomUserEdit } from "@/api/safeDanger/networkSecure"
import { updateHidden } from "@/api/safeDanger/rectificationImport"

export default {
  name: "networkSecureImportDetail",
  components: {Upload},
  computed: {
    ...mapGetters([
      'nickName',
      'companyId',
      'companyCode',
      'userId'
    ]),
  },
  props: {
    roomId: {
      type: Number,
    },
    detailId: {
      type: Number,
    },
    detailObj: {
      type: Object
    },
    isEdit: {
      type: Boolean,
      default: false
    },
    isInfo: {
      type: Boolean,
      default: false
    }
  },
  data() {
    return {
      defaultProps: {
        value: 'code',
        label: 'shortName',
        leaf: 'leaf',
        children: 'children',
        // checkStrictly: true,
        // emitPath: false,
        expandTrigger: 'hover'
      },

      // 表单参数
      formData: {
        secondCompany: undefined,
        userIdList: [],
      },

      //校验
      rules:{

        secondCompany:[{required:true, type: 'array', message:'请选择责任单位', trigger:'change'}],
        userIdList:[{required:true, message:'请选择责任人', trigger:'change'}],

      },



      // 下拉列表
      basicUnitSeconds: [],
      userList: [],

    }
  },
  created() {
    this.initData()
    this.showInfo();
  },
  mounted() {

  },
  methods: {
    secondCompanyChange(val){
      this.formData.userIdList = []
      if(val.length > 0){
        let code = val[2] || val[1]
        selectShoutUser({ regionCode: code }).then(res=>{
          this.userList = res.data
        })
      }
    },
    // 渲染表格
    showInfo() {
      if(this.detailId){
        machineroomuserId({ networkId: this.roomId, firstCompany: this.detailObj.firstCompany, secondCompany: this.detailObj.secondCompany }).then(res=>{
          let data = res.data
          this.formData.secondCompany = [ data.orgCode, data.firstCompany, data.secondCompany ]
          // this.secondCompanyChange(this.formData.secondCompany)
          // this.formData.userIdList = data.hiddenOrderUserVOS.map(el=> el.userId)
          selectShoutUser({ regionCode: data.secondCompany }).then(res=>{
            this.userList = res.data
            this.formData.userIdList = data.hiddenOrderUserVOS.map(el=> el.userId)
          })
        })
      }
    },

    /** 提交按钮 */
    submitForm: function() {
      // this.formData.firstCompany = this.companyCode.slice(0, 4)
      this.$refs["form"].validate(valid => {
        if (valid) {
          let params = {
            networkId: this.roomId,
            orgCode: this.formData.secondCompany[0],
            firstCompany: this.formData.secondCompany[1],
            secondCompany: this.formData.secondCompany[2],
            userIdList: this.formData.userIdList
          }

          if(this.detailId){
            params.id = this.detailId
            machineRoomUserEdit(params).then(res=>{
              this.$message.success(res.msg)
              this.$emit('closeRoom')
            })
          }else{
            machineRoomUserAdd(params).then(res=>{
              this.$message.success(res.msg)
              this.$emit('closeRoom')
            })
          }


          // let forms = JSON.parse(JSON.stringify(this.formData))

          // updateHidden(forms).then(response => {
          //   if (response.code === 200) {
          //     this.$message.success("修改成功");
          //     this.$emit('closeRoom', response.data)
          //   } else {
          //     this.msgError(response.msg);
          //   }
          // });
        }
      });
    },

    // 获取下拉列表
    initData(){
      getAreaTree({code: '37'}).then(res=>{
        this.basicUnitSeconds = res.data
      })

      // setTimeout(() => {
      //     this.formData.secondCompany = ['05', '0503', '050332']
      //     console.log(this.formData)
      // }, 2000);
    },






  }
}
